    public void testMap() {
        Map<String, Integer> map = new LinkedHashMap<>();
        map.put("a", 1);
        map.put("b", 2);
        Assert.assertEquals(Integer.valueOf(1), ObjectUtils.get(map, 0));
        Assert.assertEquals(Integer.valueOf(2), ObjectUtils.get(map, 1));
        Assert.assertNull(ObjectUtils.get(map, 2));
